const msg = $json.message || {};
const doc = msg.document || null;

return [{
  json: {
    chat_id: msg.chat?.id || null,
    user_id: msg.from?.id || null,
    file_id: doc?.file_id || null,
    file_name: doc?.file_name || null,
    mime_type: doc?.mime_type || null,
    text_or_caption: msg.text || msg.caption || '',
    has_document: !!doc
  }
}];

const lectureText = $json.text || '';
const inputText = $json.text_or_caption || '';
const sourceText = (lectureText || inputText || '').trim();

if (!sourceText) {
  return [{ json: { ...$json, source_text: '', is_empty: true } }];
}

let cleaned = sourceText
  .replace(/\r/g, '\n')
  .replace(/\t+/g, ' ')
  .replace(/[ ]{2,}/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{
  json: {
    ...$json,
    source_text: cleaned,
    is_empty: cleaned.length === 0
  }
}];

const text = $json.source_text || '';
const MAX_CHARS = 12000;
const OVERLAP = 500;

if (text.length <= MAX_CHARS) {
  return [{ json: { ...$json, chunk_index: 1, total_chunks: 1, chunk_text: text } }];
}

const chunks = [];
let start = 0;
while (start < text.length) {
  let end = Math.min(start + MAX_CHARS, text.length);
  if (end < text.length) {
    const boundary = text.lastIndexOf('\n', end);
    if (boundary > start + 3000) end = boundary;
  }

  chunks.push(text.slice(start, end).trim());
  if (end >= text.length) break;
  start = Math.max(0, end - OVERLAP);
}

return chunks.map((chunk, i) => ({
  json: {
    ...$json,
    chunk_index: i + 1,
    total_chunks: chunks.length,
    chunk_text: chunk
  }
}));

