const out = [];
for (const item of $input.all()) {
  const txt = item.json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  out.push({
    chat_id: item.json.chat_id,
    user_id: item.json.user_id,
    source_text: item.json.source_text,
    chunk_summary: txt.trim(),
    chunk_index: item.json.chunk_index,
    total_chunks: item.json.total_chunks
  });
}

out.sort((a,b)=>a.chunk_index-b.chunk_index);
const merged = out.map(x => `جزء ${x.chunk_index}/${x.total_chunks}:\n${x.chunk_summary}`).join('\n\n');

return [{ json: { ...out[0], merged_chunk_summaries: merged } }];

