const summary = $json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
const mcq = $item(0).$node['Gemini Generate MCQs'].json?.candidates?.[0]?.content?.parts?.[0]?.text || '';

if (!summary || !mcq) {
  return [{ json: { ...$json, ai_failed: true } }];
}

const highYield = (summary.match(/High-Yield Points[\s\S]*?(?:Important Definitions|$)/i)?.[0] || summary).trim();

const mcqSplit = mcq.split(/Answers\s*&\s*Explanations/i);
const mcqQuestions = (mcqSplit[0] || mcq).trim();
const mcqAnswers = (mcqSplit[1] || '').trim();

return [{
  json: {
    chat_id: $json.chat_id || $item(0).$node['Merge Chunk Summaries'].json.chat_id,
    final_summary: summary.trim(),
    high_yield: highYield,
    mcq_questions: mcqQuestions,
    mcq_answers: mcqAnswers || 'لم يتم إرجاع قسم Answers & Explanations بشكل منفصل.' ,
    ai_failed: false
  }
}];

const TELEGRAM_LIMIT = 3900;

function splitLong(label, content) {
  const text = `${label}\n\n${content || ''}`.trim();
  if (text.length <= TELEGRAM_LIMIT) return [text];

  const parts = [];
  let rest = text;
  while (rest.length > TELEGRAM_LIMIT) {
    let cut = rest.lastIndexOf('\n', TELEGRAM_LIMIT);
    if (cut < 1000) cut = TELEGRAM_LIMIT;
    parts.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest) parts.push(rest);
  return parts;
}

const sections = [
  ['📘 Summary', $json.final_summary],
  ['🎯 High-Yield Points', $json.high_yield],
  ['❓ MCQs', $json.mcq_questions],
  ['✅ Answers with Explanations', $json.mcq_answers]
];

const items = [];
for (const [label, content] of sections) {
  for (const msg of splitLong(label, content)) {
    items.push({ json: { chat_id: $json.chat_id, text: msg } });
  }
}
return items;
